        const result = await response.json();
        if (!response.ok) {
          throw new Error(result.error || 'Failed to update case study');
        }
        alert('Case study updated successfully!');
      } else {
        // Create new case study
        const { id: _id2, created_at: _ca2, updated_at: _ua2, ...insertData } = caseStudyData as typeof caseStudyData & { id: string; created_at: string; updated_at: string };
        const authHeader = await getAuthHeader();
        const response = await fetch('/api/case-studies', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', ...authHeader },
          credentials: 'include',
          body: JSON.stringify(insertData),
        });
        const result = await response.json();
        if (!response.ok) {
          throw new Error(result.error || 'Failed to create case study');
        }
        alert('Case study created successfully!');
      }

      setShowCreateForm(false);
