          <div>
            <h1 className="text-3xl font-bold text-white mb-2">
              Manage <span className="gradient-text-os">Case Studies</span>
            </h1>
            <p className="text-white/60">Create and manage customer success stories</p>
          </div>
          <Button
            onClick={() => setShowCreateForm(true)}
            variant="solid"
            className="bg-gradient-to-r from-[#6A27D4] to-[#8B5CF6]"
          >
            + Add New Case Study
          </Button>
        </div>

        <div className="mb-6 space-y-4">
          <SearchBar
            value={searchQuery}
            onChange={setSearchQuery}
            placeholder="Search case studies by title..."
          />
          <div className="flex gap-6">
            <FilterToggle
              label="Featured"
              value={featuredFilter}
              onChange={setFeaturedFilter}
            />
            <FilterToggle
              label="Published"
              value={publishedFilter}
              onChange={setPublishedFilter}
            />
          </div>
        </div>

        <DataTable
          data={caseStudies}
          columns={columns}
          onEdit={(caseStudy) => setEditingCaseStudy(caseStudy)}
          onDelete={handleDelete}
          emptyMessage="No case studies found. Click 'Add New Case Study' to create one."
        />
      </div>
    </AdminLayout>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { supabase } from '@/supabaseClient';
import { Guide } from '@/types/content';
import { Button } from '@/components/ui/Button';
import DataTable from '@/components/admin/DataTable';
import SearchBar from '@/components/admin/SearchBar';
import FormBuilder, { FormFieldConfig } from '@/components/admin/FormBuilder';
import AdminLayout from '@/components/admin/AdminLayout';
import { uploadFile, generateSlug } from '@/lib/upload';

export default function GuidesPage() {
  const [guides, setGuides] = useState<Guide[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [editingGuide, setEditingGuide] = useState<Guide | null>(null);

  useEffect(() => {
    fetchGuides();
  }, [searchQuery]);

  const fetchGuides = async () => {
    setLoading(true);
    try {
      let query = supabase
        .from('guides')
        .select('*')
        .order('created_at', { ascending: false });

      if (searchQuery) {
        query = query.ilike('title', `%${searchQuery}%`);
      }

      const { data, error } = await query;
      if (error) throw error;
      setGuides(data || []);
    } catch (error: unknown) {
      console.error('Error fetching guides:', error);
      alert('Failed to fetch guides: ' + (error instanceof Error ? error.message : String(error)));
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (guide: Guide) => {
    if (!window.confirm(`Are you sure you want to delete "${guide.title}"?`)) {
      return;
    }

    try {
      const { error } = await supabase.from('guides').delete().eq('id', guide.id);
      if (error) throw error;
      alert('Guide deleted successfully!');
      fetchGuides();
    } catch (error: unknown) {
      alert('Failed to delete guide: ' + (error instanceof Error ? error.message : 'Unknown error'));
    }
  };

  const handleFormSubmit = async (formData: Record<string, unknown>, files: Record<string, File | null>) => {
    try {
      let pdfUrl = formData.pdf_url;

      // Upload PDF if provided
      if (files.pdf_url) {
        const uploadResult = await uploadFile({
          bucket: 'guides',
          folder: 'pdfs',
          file: files.pdf_url,
        });
        if (!uploadResult.success) throw new Error(uploadResult.error || 'Upload failed');
        pdfUrl = uploadResult.url;
      }

      const guideData = {
        ...formData,
        slug: generateSlug((formData.slug as string) || (formData.title as string)),
        pdf_url: pdfUrl,
      };

      if (editingGuide) {
        // Update existing guide
        const { id: _id, created_at: _ca, ...updateData } = guideData as typeof guideData & { id: string; created_at: string };
        const { error } = await supabase
          .from('guides')
          .update({ ...updateData, updated_at: new Date().toISOString() })
          .eq('id', editingGuide.id);
        if (error) throw error;
